  const profiles = {};

  function add(id, seed) {
    const record = (window.OAK.PLANT_BY_ID || {})[id];
    if (!record) throw new Error(`Front-garden profile has no matching plant: ${id}`);
    const plant = record.plant;
    const kind = seed.kind || "shrub";
    const care = (CARE[kind] || CARE.shrub).map((item) => ({ ...item }));
    if (seed.careFocus) care[0] = seed.careFocus;
    const problems = (PROBLEMS[kind] || PROBLEMS.shrub).map((item) => ({ ...item }));
    if (seed.problem) problems[0] = seed.problem;
    profiles[id] = {
      version: 2,
      type: seed.type,
      badges: seed.badges,
      description: seed.description,
      floweringMonths: seed.months,
      facts: [
        { label: "Size", value: seed.size, detail: seed.sizeDetail },
        { label: "Position", value: seed.position, detail: seed.positionDetail },
        { label: "Soil", value: seed.soil, detail: seed.soilDetail },
        { label: "Hardiness", value: seed.hardiness, detail: seed.hardinessDetail },
        { label: seed.featureLabel || "Main feature", value: seed.feature, detail: seed.featureDetail },
        { label: "Identity", value: seed.identity, detail: seed.identityDetail },
      ],
      careGuide: care,
      waterSigns: {
        under: `The most useful early warning is ${seed.under}. Check below the surface before soaking the full root area.`,
        over: `Watch for ${seed.over}. If the root zone is still wet, pause watering and restore air or drainage.`,
      },
      seasons: [
        { season: "Spring", action: seed.spring },
        { season: "Summer", action: seed.summer },
        { season: "Autumn", action: seed.autumn },
        { season: "Winter", action: seed.winter },
      ],
      problems,
      ...(seed.caution ? { caution: seed.caution } : {}),
      about: seed.about,
      provenanceNote: seed.provenance,
      botanical: [
        { label: "Family", value: seed.family },
        { label: "Genus", value: seed.genus },
        { label: "Botanical name", value: plant.latin },
        { label: "Plant type", value: seed.type },
        { label: "Foliage", value: seed.foliage },
        { label: "Habit", value: seed.habit },
        { label: seed.botanicalLabel || "Name status", value: seed.botanicalValue || "Garden record accepted" },
        { label: "Native to Britain or Ireland", value: seed.native || "No" },
      ],
      oakLodge: {
        location: `${plant.position} · ${record.plantKey}`,
        added: seed.added || "Established before the 2026 journal",
        role: seed.role,
        observation: seed.observation,
        status: seed.status,
      },
      sources: [seed.source, OAK_SOURCE],
    };
  }

  function cloneAt(id, sourceId, description, role, observation) {
    const source = profiles[sourceId];
    const record = window.OAK.PLANT_BY_ID[id];
    if (!source || !record) throw new Error(`Cannot clone front-garden profile ${id} from ${sourceId}`);
    profiles[id] = JSON.parse(JSON.stringify(source));
    profiles[id].description = description;
    profiles[id].botanical[2].value = record.plant.latin;
    profiles[id].oakLodge.location = `${record.plant.position} · ${record.plantKey}`;
    profiles[id].oakLodge.role = role;
    profiles[id].oakLodge.observation = observation;
  }

